    function initSelectorOptions() {
      const selector = document.getElementById('slide-selector');
      selector.innerHTML = '';

      // Cover option
      const coverOpt = document.createElement('option');
      coverOpt.value = '0';
      coverOpt.textContent = '封面：2026 一起背單字';
      selector.appendChild(coverOpt);

      // Word options
      VOCAB_DATA.forEach((item, idx) => {
        const opt = document.createElement('option');
        const num = String(idx + 1).padStart(2, '0');
        opt.value = String(idx + 1);
        opt.textContent = `${num}. ${item.word}`;
        selector.appendChild(opt);
      });
    }

    /* Render current active slide */
    function renderSlide() {
      const container = document.getElementById('slide-content-host');
      const progressBar = document.getElementById('progress-bar-fill');
      const selector = document.getElementById('slide-selector');
      const indicator = document.getElementById('slide-indicator');

      // Update progress bar
      const progressPercent = (currentSlide / (totalSlides - 1)) * 100;
      progressBar.style.width = `${progressPercent}%`;

      // Update dropdown selector
      selector.value = String(currentSlide);

      if (currentSlide === 0) {
        indicator.textContent = '封面';
        container.innerHTML = renderCoverSlide();
      } else {
        const item = VOCAB_DATA[currentSlide - 1];
        const numStr = String(currentSlide).padStart(2, '0');
        const totalStr = String(VOCAB_DATA.length).padStart(2, '0');
        indicator.textContent = `${numStr} / ${totalStr}`;
        container.innerHTML = renderWordSlide(item, numStr, totalStr);
      }

      // If auto-speak enabled & not cover slide, pronounce the word
      if (autoSpeakEnabled && currentSlide > 0) {
        const currentItem = VOCAB_DATA[currentSlide - 1];
        setTimeout(() => {
          speakText(currentItem.word, 'word');
        }, 180);
      }
    }

