  <script>
    /* Responsive stage scaling algorithm */
    function fitPresentationStage() {
      const stage = document.getElementById('presentation-stage');
      const viewport = document.getElementById('presentation-viewport');
      if (!stage || !viewport) return;

      const viewportWidth = viewport.clientWidth;
      const viewportHeight = viewport.clientHeight;

      // Mobile check: width < 768px -> release fixed scale, switch to fluid RWD
      if (window.innerWidth < 768) {
        stage.style.transform = 'none';
        stage.style.width = '100%';
        stage.style.height = 'auto';
        return;
      }

      // Desktop / Landscape: 1200 x 675 (16:9)
      const baseWidth = 1200;
      const baseHeight = 675;

      stage.style.width = `${baseWidth}px`;
      stage.style.height = `${baseHeight}px`;

      // Allow 24px margin
      const padding = 24;
      const availableW = viewportWidth - padding;
      const availableH = viewportHeight - padding;

      const scaleX = availableW / baseWidth;
      const scaleY = availableH / baseHeight;
      const scale = Math.min(scaleX, scaleY, 1.25);

      stage.style.transform = `scale(${scale})`;
    }

    window.addEventListener('resize', fitPresentationStage);
    window.addEventListener('orientationchange', () => {
      setTimeout(fitPresentationStage, 200);
    });
  </script>

  <script>
    let voices = [];

    function loadVoices() {
      if ('speechSynthesis' in window) {
        voices = window.speechSynthesis.getVoices();
      }
    }

    if ('speechSynthesis' in window) {
      window.speechSynthesis.onvoiceschanged = loadVoices;
      loadVoices();
    }

    /* Pronounce text with word correction table */
    function speakText(rawText, type = 'word') {
      if (!('speechSynthesis' in window)) {
        return;
      }

      window.speechSynthesis.cancel(); // Stop any pending speech

      let cleaned = rawText.trim();

      // Apply correction table if exact or starting match
      if (SPEECH_CORRECTIONS[cleaned]) {
        cleaned = SPEECH_CORRECTIONS[cleaned];
      } else {
        // Replace punctuation words if in sentences
        Object.keys(SPEECH_CORRECTIONS).forEach(key => {
          const regex = new RegExp(`\\b${key}\\b`, 'g');
          cleaned = cleaned.replace(regex, SPEECH_CORRECTIONS[key]);
        });
      }

      const utterance = new SpeechSynthesisUtterance(cleaned);
      utterance.lang = 'en-US';

      // Pick preferred English natural voice
      if (voices.length === 0) loadVoices();
      const preferredVoice = voices.find(v => (v.lang === 'en-US' || v.lang.startsWith('en')) && (v.name.includes('Samantha') || v.name.includes('Natural') || v.name.includes('Google') || v.name.includes('Jenny')));
      if (preferredVoice) {
        utterance.voice = preferredVoice;
      }

      // Slightly slower speech rate for elementary students
      utterance.rate = type === 'word' ? 0.85 : 0.9;
      utterance.pitch = 1.05;

      const speakBtn = document.getElementById('btn-speak-word');
      utterance.onstart = () => {
        isSpeaking = true;
        if (speakBtn) speakBtn.classList.add('speaking-pulse');
      };
      utterance.onend = () => {
        isSpeaking = false;
        if (speakBtn) speakBtn.classList.remove('speaking-pulse');
      };
      utterance.onerror = () => {
        isSpeaking = false;
        if (speakBtn) speakBtn.classList.remove('speaking-pulse');
      };

      window.speechSynthesis.speak(utterance);
    }

    function speakCurrentWord() {
      if (currentSlide === 0) {
        speakText("Welcome to English vocabulary class!");
      } else {
        const item = VOCAB_DATA[currentSlide - 1];
        speakText(item.word, 'word');
      }
    }

    function toggleAutoSpeech() {
      autoSpeakEnabled = !autoSpeakEnabled;
      const icon = document.getElementById('auto-speak-icon');
      const text = document.getElementById('auto-speak-text');
      const btn = document.getElementById('btn-toggle-auto');

      if (autoSpeakEnabled) {
        icon.className = 'fa-solid fa-toggle-on text-emerald-600 text-base';
        text.textContent = '自動發音: 開';
        btn.classList.remove('border-slate-300', 'bg-slate-50', 'text-slate-600');
        btn.classList.add('border-emerald-500', 'bg-emerald-50', 'text-emerald-800');
        speakCurrentWord();
      } else {
        icon.className = 'fa-solid fa-toggle-off text-slate-400 text-base';
        text.textContent = '自動發音: 關';
        btn.classList.remove('border-emerald-500', 'bg-emerald-50', 'text-emerald-800');
        btn.classList.add('border-slate-300', 'bg-slate-50', 'text-slate-600');
      }
    }
  </script>

  <script>
    function goToSlide(index) {
      if (index < 0) index = 0;
      if (index >= totalSlides) index = totalSlides - 1;
      currentSlide = index;
      renderSlide();
    }

    function goToNextSlide() {
      if (currentSlide < totalSlides - 1) {
        goToSlide(currentSlide + 1);
      } else {
        goToSlide(0);
      }
    }

    function goToPrevSlide() {
      if (currentSlide > 0) {
        goToSlide(currentSlide - 1);
      }
    }

    function onSelectorChange(val) {
      goToSlide(parseInt(val, 10));
    }

    /* Keyboard navigation: Left, Right, Spacebar, F, S */
    window.addEventListener('keydown', (e) => {
      if (e.target.tagName === 'SELECT' || e.target.tagName === 'INPUT') return;

      if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
        e.preventDefault();
        goToNextSlide();
      } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
        e.preventDefault();
        goToPrevSlide();
      } else if (e.key === 'f' || e.key === 'F') {
        e.preventDefault();
        toggleFullscreen();
      } else if (e.key === 's' || e.key === 'S') {
        e.preventDefault();
        speakCurrentWord();
      }
    });

    /* Touch swipe gesture for tablet & mobile */
    let touchStartX = 0;
    let touchStartY = 0;
    let touchEndX = 0;
    let touchEndY = 0;

    window.addEventListener('touchstart', (e) => {
      touchStartX = e.changedTouches[0].screenX;
      touchStartY = e.changedTouches[0].screenY;
    }, { passive: true });

    window.addEventListener('touchend', (e) => {
      touchEndX = e.changedTouches[0].screenX;
      touchEndY = e.changedTouches[0].screenY;
      handleSwipeGesture();
    }, { passive: true });

    function handleSwipeGesture() {
      const diffX = touchEndX - touchStartX;
      const diffY = touchEndY - touchStartY;
      const threshold = 55;

      if (Math.abs(diffX) > Math.abs(diffY) && Math.abs(diffX) > threshold) {
        if (diffX < 0) {
          goToNextSlide();
        } else {
          goToPrevSlide();
        }
      }
    }

    /* Fullscreen API Handling */
    function toggleFullscreen() {
      const icon = document.getElementById('fullscreen-icon');
      if (!document.fullscreenElement) {
        document.documentElement.requestFullscreen().then(() => {
          if (icon) icon.className = 'fa-solid fa-compress';
        }).catch(err => {
          console.warn('Fullscreen error:', err);
        });
      } else {
        if (document.exitFullscreen) {
          document.exitFullscreen().then(() => {
            if (icon) icon.className = 'fa-solid fa-expand';
          });
        }
      }
    }

    document.addEventListener('fullscreenchange', () => {
      const icon = document.getElementById('fullscreen-icon');
      if (!icon) return;
      if (document.fullscreenElement) {
        icon.className = 'fa-solid fa-compress';
      } else {
        icon.className = 'fa-solid fa-expand';
      }
      fitPresentationStage();
    });

    /* Initialize application on DOM ready */
    window.addEventListener('DOMContentLoaded', () => {
      initSelectorOptions();
      renderSlide();
      fitPresentationStage();
    });
  </script>
